/* ========================================
   OpenLearnHub - Shared Design System CSS
   ======================================== */

/* CSS Custom Properties */
:root {
  /* Colors */
  --color-primary: #0A0A23;
  --color-primary-light: #1a1a3e;
  --color-accent: #FEAC32;
  --color-accent-hover: #e0990f;
  --color-link: #002EAD;
  --color-link-hover: #0040e0;
  --color-white: #FFFFFF;
  --color-bg-light: #F8F9FA;
  --color-bg-gray: #F0F1F3;
  --color-text: #1a1a2e;
  --color-text-light: #6B7280;
  --color-border: #E5E7EB;
  --color-success: #10B981;
  --color-error: #EF4444;

  /* Typography */
  --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-bold: 600;
  --font-semibold: 500;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;

  /* Layout */
  --max-width: 1200px;
  --max-width-content: 800px;
  --border-radius: 8px;
  --border-radius-lg: 12px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-normal: 300ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-primary);
  color: var(--color-text);
  background-color: var(--color-white);
  line-height: 1.6;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-link-hover);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Utility Classes */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* ========================================
   Header
   ======================================== */
.header {
  background-color: var(--color-primary);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  max-width: var(--max-width);
  margin: 0 auto;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: var(--color-white);
  font-size: 1.25rem;
  font-weight: var(--font-bold);
  text-decoration: none;
}

.logo:hover {
  color: var(--color-white);
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--color-primary);
}

/* Desktop Navigation */
.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.nav-desktop a {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.9rem;
  font-weight: var(--font-semibold);
  transition: color var(--transition-fast);
}

.nav-desktop a:hover {
  color: var(--color-white);
}

/* Search Bar */
.search-bar {
  flex: 1;
  max-width: 300px;
  margin: 0 var(--space-xl);
}

.search-bar input {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: var(--border-radius);
  color: var(--color-white);
  font-size: 0.875rem;
  outline: none;
  transition: all var(--transition-fast);
}

.search-bar input::placeholder {
  color: rgba(255, 255, 255, 0.5);
}

.search-bar input:focus {
  background: rgba(255, 255, 255, 0.15);
  border-color: var(--color-accent);
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--space-sm);
  color: var(--color-white);
}

.menu-toggle i {
  font-size: 1.5rem;
}

/* Mobile Navigation */
.nav-mobile {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--color-primary);
  padding: var(--space-md) var(--space-lg);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-mobile.active {
  display: block;
}

.nav-mobile a {
  display: block;
  color: var(--color-white);
  padding: var(--space-md) 0;
  font-weight: var(--font-semibold);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-mobile a:last-child {
  border-bottom: none;
}

/* ========================================
   Banner
   ======================================== */
.banner {
  background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-primary) 100%);
  padding: var(--space-md) var(--space-lg);
  text-align: center;
}

.banner-text {
  color: var(--color-white);
  font-size: 0.9rem;
  font-weight: var(--font-semibold);
}

.banner-text a {
  color: var(--color-accent);
  text-decoration: underline;
}

/* ========================================
   Hero Featured Article
   ======================================== */
.featured-article {
  background: var(--color-bg-light);
  padding: var(--space-3xl) var(--space-lg);
}

.featured-card {
  max-width: var(--max-width);
  margin: 0 auto;
  position: relative;
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  min-height: 400px;
  display: flex;
  align-items: flex-end;
}

.featured-card img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-card-content {
  position: relative;
  z-index: 2;
  padding: var(--space-xl);
  background: linear-gradient(transparent, rgba(10, 10, 35, 0.9));
  width: 100%;
}

.tag-label {
  display: inline-block;
  padding: var(--space-xs) var(--space-sm);
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: var(--font-bold);
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--space-md);
}

.tag-label.ai {
  background: #FF6B6B;
  color: var(--color-white);
}

.tag-label.web-scraping {
  background: #4ECDC4;
  color: var(--color-primary);
}

.tag-label.databases {
  background: #9B59B6;
  color: var(--color-white);
}

.tag-label.elasticsearch {
  background: #3498DB;
  color: var(--color-white);
}

.tag-label.data-engineering {
  background: #27AE60;
  color: var(--color-white);
}

.featured-card-content h2 {
  color: var(--color-white);
  font-size: 2rem;
  font-weight: var(--font-bold);
  margin-bottom: var(--space-md);
  line-height: 1.3;
}

.featured-author {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.9rem;
}

.featured-author img {
  position: static;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid var(--color-accent);
}

/* ========================================
   Article Grid
   ======================================== */
.article-section {
  padding: var(--space-3xl) var(--space-lg);
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-title {
  font-size: 1.5rem;
  font-weight: var(--font-bold);
  margin-bottom: var(--space-xl);
  color: var(--color-text);
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.article-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.article-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.article-card-image {
  position: relative;
  height: 180px;
  overflow: hidden;
}

.article-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-normal);
}

.article-card:hover .article-card-image img {
  transform: scale(1.05);
}

.article-card-content {
  padding: var(--space-lg);
}

.article-card-content .tag-label {
  margin-bottom: var(--space-sm);
}

.article-card-content h3 {
  font-size: 1.1rem;
  font-weight: var(--font-bold);
  margin-bottom: var(--space-md);
  line-height: 1.4;
  color: var(--color-text);
}

.article-card-content h3 a {
  color: inherit;
  text-decoration: none;
}

.article-card-content h3 a:hover {
  color: var(--color-link);
}

.article-author {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: var(--color-text-light);
  font-size: 0.85rem;
}

.article-author img {
  width: 28px;
  height: 28px;
  border-radius: 50%;
}

.article-author .separator {
  margin: 0 var(--space-xs);
}

/* Load More Button */
.load-more-container {
  text-align: center;
  margin-top: var(--space-2xl);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-md) var(--space-xl);
  font-size: 0.9rem;
  font-weight: var(--font-semibold);
  border-radius: var(--border-radius);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: var(--color-primary-light);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-accent:hover {
  background: var(--color-accent-hover);
}

/* ========================================
   Footer
   ======================================== */
.footer {
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--space-3xl) var(--space-lg);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--space-3xl);
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-mission {
  font-size: 0.9rem;
  line-height: 1.7;
  opacity: 0.85;
}

.footer-links h4 {
  font-size: 0.85rem;
  font-weight: var(--font-bold);
  margin-bottom: var(--space-md);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-accent);
}

.footer-links ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm) var(--space-xl);
}

.footer-links li {
  margin-bottom: var(--space-sm);
}

.footer-links a {
  color: rgba(255, 255, 255, 0.75);
  font-size: 0.85rem;
}

.footer-links a:hover {
  color: var(--color-white);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: var(--space-2xl) auto 0;
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 0.8rem;
  opacity: 0.6;
  text-align: center;
}

/* ========================================
   Tag Page Styles
   ======================================== */
.tag-header {
  padding: var(--space-3xl) var(--space-lg);
  text-align: center;
  background: var(--color-bg-light);
}

.tag-header h1 {
  font-size: 2.5rem;
  font-weight: var(--font-bold);
  margin-bottom: var(--space-sm);
  color: var(--color-text);
}

.tag-header .post-count {
  font-size: 1rem;
  color: var(--color-text-light);
}

.popular-tags {
  padding: var(--space-lg) var(--space-lg);
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
}

.popular-tags-inner {
  display: flex;
  gap: var(--space-md);
  max-width: var(--max-width);
  margin: 0 auto;
  justify-content: center;
}

.popular-tag {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-md);
  background: var(--color-bg-gray);
  border-radius: 20px;
  font-size: 0.85rem;
  color: var(--color-text);
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.popular-tag:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.popular-tag .count {
  font-weight: var(--font-bold);
  color: var(--color-text-light);
}

.popular-tag:hover .count {
  color: var(--color-accent);
}

/* ========================================
   Learn Page Styles
   ======================================== */
.welcome-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 100%);
  padding: var(--space-3xl) var(--space-lg);
  text-align: center;
}

.welcome-cta h1 {
  color: var(--color-white);
  font-size: 2rem;
  margin-bottom: var(--space-md);
}

.welcome-cta p {
  color: rgba(255, 255, 255, 0.85);
  font-size: 1.1rem;
  max-width: 600px;
  margin: 0 auto;
}

.curriculum-section {
  padding: var(--space-3xl) var(--space-lg);
  max-width: var(--max-width);
  margin: 0 auto;
}

.curriculum-section h2 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xl);
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.cert-card {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-lg);
  background: var(--color-bg-light);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--color-border);
  transition: all var(--transition-fast);
}

.cert-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.cert-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.cert-card h3 {
  font-size: 1rem;
  font-weight: var(--font-semibold);
  color: var(--color-text);
}

.daily-challenge {
  background: var(--color-bg-light);
  padding: var(--space-xl);
  border-radius: var(--border-radius-lg);
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.daily-challenge h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
}

.daily-challenge p {
  color: var(--color-text-light);
  margin-bottom: var(--space-lg);
}

.challenge-links {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
}

.course-category {
  margin-bottom: var(--space-2xl);
}

.course-category h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
  color: var(--color-text);
}

.course-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.course-tag {
  padding: var(--space-sm) var(--space-md);
  background: var(--color-bg-gray);
  border-radius: 20px;
  font-size: 0.9rem;
  color: var(--color-text);
  transition: all var(--transition-fast);
}

.course-tag:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

/* ========================================
   Donate Page Styles
   ======================================== */
.donation-hero {
  background: linear-gradient(135deg, var(--color-primary) 0%, #1a1a4a 100%);
  padding: var(--space-3xl) var(--space-lg);
  text-align: center;
}

.donation-hero h1 {
  color: var(--color-white);
  font-size: 2.5rem;
  margin-bottom: var(--space-lg);
}

.donation-hero p {
  color: rgba(255, 255, 255, 0.85);
  font-size: 1.1rem;
  max-width: 700px;
  margin: 0 auto var(--space-xl);
  line-height: 1.7;
}

.donation-form {
  max-width: 600px;
  margin: 0 auto;
  background: var(--color-white);
  border-radius: var(--border-radius-lg);
  padding: var(--space-xl);
  box-shadow: var(--shadow-lg);
}

.amount-selector {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
  justify-content: center;
}

.amount-tab {
  flex: 1;
  max-width: 100px;
  padding: var(--space-md);
  background: var(--color-bg-gray);
  border: 2px solid transparent;
  border-radius: var(--border-radius);
  font-size: 1rem;
  font-weight: var(--font-bold);
  cursor: pointer;
  transition: all var(--transition-fast);
  color: var(--color-text);
}

.amount-tab:hover {
  border-color: var(--color-accent);
}

.amount-tab.active {
  background: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-primary);
}

.donation-description {
  text-align: center;
  padding: var(--space-md);
  background: var(--color-bg-light);
  border-radius: var(--border-radius);
  margin-bottom: var(--space-lg);
  font-size: 0.95rem;
  color: var(--color-text);
  min-height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.donate-btn {
  width: 100%;
  padding: var(--space-md);
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 1.1rem;
  font-weight: var(--font-bold);
  border: none;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.donate-btn:hover {
  background: var(--color-accent-hover);
}

.donation-sub-label {
  text-align: center;
  margin-top: var(--space-md);
  font-size: 0.8rem;
  color: var(--color-text-light);
}

.donation-sub-label a {
  color: var(--color-text-light);
  text-decoration: underline;
}

.supporter-benefits {
  padding: var(--space-3xl) var(--space-lg);
  max-width: var(--max-width);
  margin: 0 auto;
}

.supporter-benefits h2 {
  text-align: center;
  font-size: 1.75rem;
  margin-bottom: var(--space-xl);
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
  max-width: 700px;
  margin: 0 auto;
}

.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--color-bg-light);
  border-radius: var(--border-radius);
}

.benefit-icon {
  width: 24px;
  height: 24px;
  background: var(--color-success);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: 0.75rem;
  flex-shrink: 0;
}

.benefit-item p {
  font-size: 0.95rem;
  color: var(--color-text);
}

.current-initiatives {
  padding: var(--space-2xl) var(--space-lg);
  background: var(--color-bg-light);
}

.initiatives-list {
  max-width: var(--max-width);
  margin: 0 auto;
}

.initiatives-list h2 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xl);
  text-align: center;
}

.initiatives-list ul {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
}

.initiatives-list li {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-md);
  background: var(--color-white);
  border-radius: var(--border-radius);
}

.initiatives-list li::before {
  content: "✓";
  color: var(--color-success);
  font-weight: var(--font-bold);
}

.community-achievements {
  padding: var(--space-3xl) var(--space-lg);
  max-width: var(--max-width);
  margin: 0 auto;
}

.community-achievements h2 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xl);
  text-align: center;
}

.achievements-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-md) var(--space-2xl);
}

.achievements-list li {
  font-size: 1rem;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.achievements-list .highlight {
  font-weight: var(--font-bold);
  font-size: 1.2rem;
  color: var(--color-primary);
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-3xl) var(--space-lg);
  background: var(--color-bg-light);
}

.faq-inner {
