  border: none;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.donate-btn:hover {
  background: var(--color-accent-hover);
}

.donation-sub-label {
  text-align: center;
  margin-top: var(--space-md);
  font-size: 0.8rem;
  color: var(--color-text-light);
}

.donation-sub-label a {
  color: var(--color-text-light);
  text-decoration: underline;
}

.supporter-benefits {
  padding: var(--space-3xl) var(--space-lg);
  max-width: var(--max-width);
  margin: 0 auto;
}

.supporter-benefits h2 {
  text-align: center;
  font-size: 1.75rem;
  margin-bottom: var(--space-xl);
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
  max-width: 700px;
  margin: 0 auto;
}

.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--color-bg-light);
  border-radius: var(--border-radius);
}

.benefit-icon {
  width: 24px;
  height: 24px;
  background: var(--color-success);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: 0.75rem;
  flex-shrink: 0;
}

.benefit-item p {
  font-size: 0.95rem;
  color: var(--color-text);
}

.current-initiatives {
  padding: var(--space-2xl) var(--space-lg);
  background: var(--color-bg-light);
}

.initiatives-list {
  max-width: var(--max-width);
  margin: 0 auto;
}

.initiatives-list h2 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xl);
  text-align: center;
}

.initiatives-list ul {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
}

.initiatives-list li {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-md);
  background: var(--color-white);
  border-radius: var(--border-radius);
}

.initiatives-list li::before {
  content: "✓";
  color: var(--color-success);
  font-weight: var(--font-bold);
}

.community-achievements {
  padding: var(--space-3xl) var(--space-lg);
  max-width: var(--max-width);
  margin: 0 auto;
}

.community-achievements h2 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xl);
  text-align: center;
}

.achievements-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-md) var(--space-2xl);
}

.achievements-list li {
  font-size: 1rem;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.achievements-list .highlight {
  font-weight: var(--font-bold);
  font-size: 1.2rem;
  color: var(--color-primary);
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-3xl) var(--space-lg);
  background: var(--color-bg-light);
}

.faq-inner {
  max-width: var(--max-width-content);
  margin: 0 auto;
}

.faq-inner h2 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xl);
  text-align: center;
}

.faq-list {
  border-radius: var(--border-radius-lg);
  overflow: hidden;
}

.faq-item {
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border);
}

.faq-item:last-child {
  border-bottom: none;
}

.faq-question {
  width: 100%;
  padding: var(--space-lg);
  background: none;
  border: none;
  text-align: left;
  font-size: 1rem;
  font-weight: var(--font-semibold);
  color: var(--color-text);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
  transition: background var(--transition-fast);
}

.faq-question:hover {
  background: var(--color-bg-light);
}

.faq-question i {
  transition: transform var(--transition-normal);
  color: var(--color-text-light);
}

.faq-item.active .faq-question i {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-normal);
}

.faq-answer-inner {
  padding: 0 var(--space-lg) var(--space-lg);
  color: var(--color-text-light);
  font-size: 0.95rem;
  line-height: 1.7;
}

.faq-item.active .faq-answer {
  max-height: 500px;
}

/* ========================================
   Responsive Styles
   ======================================== */
@media (max-width: 968px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cert-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-xl);
  }
}

@media (max-width: 768px) {
  .nav-desktop {
    display: none;
  }

  .search-bar {
    display: none;
  }

  .menu-toggle {
    display: block;
  }

  .article-grid {
    grid-template-columns: 1fr;
  }

  .cert-grid {
    grid-template-columns: 1fr;
  }

  .benefits-grid {
    grid-template-columns: 1fr;
  }

  .initiatives-list ul {
    grid-template-columns: 1fr;
  }

  .featured-card-content h2 {
    font-size: 1.5rem;
  }

  .donation-hero h1 {
    font-size: 1.75rem;
  }

  .amount-selector {
    flex-wrap: wrap;
  }

  .amount-tab {
    flex: 1 0 calc(50% - var(--space-sm));
    max-width: none;
  }
}

/* ========================================
   Animations
   ======================================== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.article-card {
  animation: fadeIn 0.4s ease forwards;
}

.article-card:nth-child(2) { animation-delay: 0.1s; }
.article-card:nth-child(3) { animation-delay: 0.2s; }
.article-card:nth-child(4) { animation-delay: 0.3s; }
.article-card:nth-child(5) { animation-delay: 0.4s; }
